import * as THREE from 'three';

export type WesternSaddleMountTarget = 'horse' | 'catlion' | 'stag';

export interface WesternSaddleMountPreset {
  scale: [number, number, number];
  backY: number;
  backZ: number;
  pitchDeg: number;
  archLift: number;
  rockerLift: number;
  flankFlare: number;
  joints: [number, number, number]; // [rearSpine, midSpine, frontWithers]
}

